mapper.select:
select * from item where is_deleted != 1
AND title like concat("%",#{keyword},"%")
order by id limit #{offset}, #{pageSize}

select * from item i inner join category c on i.category_id = c.id where i.is_deleted = 0
and ( i.title like concat('%', #{keyword}, '%') or c.name like concat('%', #{keyword}, '%') )
order by i.id limit #{offset}, #{pageSize}

select c.name as categoryName,c.category_image,i.* from category c left join item i on i.category_id = c.id where i.is_deleted = 0 and c.is_deleted = 0
and ( i.title like concat('%', #{keyword}, '%') or c.name like concat('%', #{keyword}, '%') )
order by i.id limit #{offset}, #{pageSize}
